*{box-sizing:border-box} :root{--ink:#172321;--muted:#8b9b93;--cream:#f1eee5;--lime:#d6ee87;--orange:#ee9b64;--glass:rgba(17,28,27,.78)}html,body{height:100%;margin:0;background:#101a1c;color:white;font-family:Manrope,system-ui,sans-serif;overflow:hidden}button{font:inherit;color:inherit;cursor:pointer;border:0}.game-shell{position:relative;width:100vw;height:100dvh;min-height:520px;overflow:hidden;background:#778c89;isolation:isolate}#scene{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(5,15,17,.42),transparent 22%,transparent 60%,rgba(4,8,9,.5)),linear-gradient(90deg,rgba(8,16,16,.22),transparent 25%,transparent 72%,rgba(8,16,16,.1));z-index:1}.topbar{position:absolute;z-index:3;top:0;left:0;right:0;height:82px;padding:20px 4.1%;display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:11px;color:white;text-decoration:none;font-size:15px;letter-spacing:1.9px;font-weight:800;line-height:1}.brand-mark{width:37px;height:37px;border:1px solid rgba(255,255,255,.55);display:grid;place-items:center;font-family:Georgia,serif;font-size:23px;font-weight:400;color:var(--lime);transform:skew(-7deg)}.brand small{display:block;font:9px 'DM Mono',monospace;letter-spacing:2px;color:rgba(255,255,255,.62);margin-top:5px}.brand-light{font-weight:400;color:rgba(255,255,255,.72)}.lesson-pill{display:flex;align-items:center;gap:11px;border:1px solid rgba(255,255,255,.2);border-radius:30px;background:rgba(17,27,26,.36);backdrop-filter:blur(10px);padding:10px 15px;font:10px 'DM Mono',monospace;letter-spacing:1px;color:#e3e7dd}.lesson-pill i{height:11px;width:1px;background:rgba(255,255,255,.3)}.live-dot,.speed-dot{width:6px;height:6px;border-radius:50%;background:var(--lime);box-shadow:0 0 9px var(--lime)}.top-actions{display:flex;gap:8px}.icon-btn{width:38px;height:38px;border:1px solid rgba(255,255,255,.26);border-radius:50%;background:rgba(17,27,26,.32);backdrop-filter:blur(9px);font-size:15px}.icon-btn:hover,.control-btn:hover{background:rgba(214,238,135,.2)}.mission-card{position:absolute;z-index:2;left:6.1%;top:19%;width:320px;text-shadow:0 2px 14px rgba(0,0,0,.2);pointer-events:none}.eyebrow{display:flex;align-items:center;gap:9px;color:var(--lime);font:10px 'DM Mono',monospace;letter-spacing:1.8px}.eyebrow-line{height:1px;width:24px;background:var(--lime)}.mission-card h1{font-size:clamp(34px,4vw,54px);line-height:1.02;letter-spacing:-2.3px;margin:17px 0 12px;font-weight:600}.mission-card p{font-size:13px;line-height:1.7;color:rgba(255,255,255,.82);max-width:290px;margin:0}.mission-progress{display:flex;align-items:center;gap:12px;margin:23px 0 15px;font:9px 'DM Mono',monospace;letter-spacing:1px;color:rgba(255,255,255,.68)}.progress-track{height:2px;width:155px;background:rgba(255,255,255,.32)}.progress-track span{height:100%;width:0;display:block;background:var(--lime);transition:width .5s}.tip-row{display:flex;gap:9px;align-items:center;font-size:10px;color:rgba(255,255,255,.82)}.tip-row b{color:var(--lime);font-size:9px;letter-spacing:.7px}.tip-icon{font-size:17px;color:var(--lime)}.route-badge{position:absolute;z-index:2;top:42%;right:5.2%;display:flex;gap:12px;align-items:center;background:rgba(21,34,32,.48);backdrop-filter:blur(8px);padding:12px 16px;border:1px solid rgba(255,255,255,.16);border-radius:3px}.route-icon{width:31px;height:31px;border:1px solid rgba(214,238,135,.5);border-radius:50%;display:grid;place-items:center;color:var(--lime);font-size:17px}.route-badge b,.route-badge small{display:block}.route-badge b{font:9px 'DM Mono',monospace;letter-spacing:1.1px}.route-badge small{font:8px 'DM Mono',monospace;color:#bbc4b9;margin-top:5px;letter-spacing:.7px}.speed-card{position:absolute;z-index:4;right:5.2%;top:13%;width:116px;height:116px;border:1px solid rgba(255,255,255,.35);border-radius:50%;background:rgba(17,28,27,.39);backdrop-filter:blur(10px);display:flex;flex-direction:column;align-items:center;justify-content:center}.speed-value{display:flex;align-items:baseline;gap:4px}.speed-value span{font:43px 'DM Mono',monospace;letter-spacing:-3px}.speed-value small{font:8px 'DM Mono',monospace;color:rgba(255,255,255,.67)}.speed-bottom{display:flex;align-items:center;gap:6px;font:8px 'DM Mono',monospace;letter-spacing:1px;color:rgba(255,255,255,.74);margin-top:1px}.speed-dot{width:5px;height:5px;background:#aeb9a3;box-shadow:none}.gear-card{position:absolute;z-index:3;right:calc(5.2% + 128px);top:16.5%;display:flex;flex-direction:column;align-items:center;width:69px;color:white;text-shadow:0 1px 5px #253331}.gear-card small,.gear-card span{font:8px 'DM Mono',monospace;letter-spacing:1.2px;color:rgba(255,255,255,.72)}.gear-card strong{font:29px 'DM Mono',monospace;color:var(--lime);line-height:1.1}.gear-card span{font-size:7px}.status-pills{position:absolute;z-index:3;right:5.4%;top:calc(13% + 130px);display:flex;gap:7px}.status-pill{font:8px 'DM Mono',monospace;letter-spacing:.5px;padding:7px 9px;background:rgba(14,24,24,.46);border:1px solid rgba(255,255,255,.16);border-radius:2px;color:#e6e9df}.status-pill i{display:inline-block;width:5px;height:5px;border-radius:50%;background:#df755c;margin:0 5px 1px 0}.status-pill.on i{background:var(--lime);box-shadow:0 0 6px var(--lime)}.warning-toast{position:absolute;z-index:8;top:31%;left:50%;transform:translate(-50%,-10px);padding:10px 16px;border:1px solid rgba(238,155,100,.65);background:rgba(32,23,21,.85);font:10px 'DM Mono',monospace;letter-spacing:.5px;color:#ffd2af;opacity:0;transition:.22s;pointer-events:none}.warning-toast.show{opacity:1;transform:translate(-50%,0)}
/* Cockpit silhouette */
.cockpit{position:absolute;z-index:2;left:0;right:0;bottom:-1px;height:36%;min-height:205px;background:linear-gradient(180deg,#263234 0%,#1b2527 24%,#11191b 82%);clip-path:polygon(0 26%,15% 11%,34% 0,66% 0,85% 11%,100% 26%,100% 100%,0 100%);box-shadow:0 -20px 40px rgba(0,0,0,.38)}.cockpit:before{content:"";position:absolute;left:0;right:0;top:13%;height:2px;background:linear-gradient(90deg,#596565,#9da6a0 50%,#4b5657);opacity:.7}.dashboard-glow{position:absolute;top:0;left:20%;width:60%;height:28%;background:radial-gradient(ellipse,rgba(194,208,184,.16),transparent 70%)}.cluster{position:absolute;top:12%;left:50%;transform:translateX(-50%);height:105px;width:330px;display:flex;align-items:center;justify-content:space-between}.gauge{position:relative;width:102px;height:102px;border-radius:50%;border:5px solid #080f11;background:radial-gradient(circle at 50% 44%,#273438,#111a1c 66%);box-shadow:0 0 0 2px #3a4547,inset 0 0 0 1px #526061,0 4px 12px #080c0d}.gauge canvas{width:100%;height:100%}.gauge-caption{position:absolute;bottom:16px;left:0;right:0;text-align:center;font:7px 'DM Mono',monospace;letter-spacing:1px;color:#9daaa4}.cluster-center{width:110px;text-align:center}.cluster-brand{font:8px 'DM Mono',monospace;letter-spacing:1.2px;color:#cbd2c8}.cluster-brand span{color:var(--lime)}.cluster-lights{margin:12px auto 9px;display:flex;justify-content:center;gap:13px}.cluster-lights i{width:5px;height:5px;border-radius:50%;background:#a84637;opacity:.5}.cluster-lights .light-seat{background:#9da653}.cluster-clock{font:9px 'DM Mono',monospace;color:#a8c98c;letter-spacing:1px}.dash-seam{position:absolute;bottom:19%;height:1px;width:100%;background:linear-gradient(90deg,transparent,#394447 18%,#465052 50%,#303b3e 82%,transparent)}.dash-controls{position:absolute;left:50%;bottom:23%;transform:translateX(-50%);width:100px;display:flex;justify-content:space-between;color:#86918e;font-size:8px}.steering-wrap{position:absolute;bottom:-34px;left:50%;transform:translateX(-50%);width:200px;height:164px;display:flex;justify-content:center}.steering-wheel{width:170px;height:170px;border:13px solid #090f10;border-radius:50%;position:relative;box-shadow:0 0 0 2px #465052,0 7px 18px #090d0d;transition:transform .15s}.wheel-rim{position:absolute;inset:3px;border:2px solid #354043;border-radius:50%}.wheel-spoke{position:absolute;background:linear-gradient(90deg,#0b1112,#293234);height:67px;width:12px;top:48px;border-radius:4px}.spoke-left{left:36px;transform:rotate(38deg)}.spoke-right{right:36px;transform:rotate(-38deg)}.wheel-hub{position:absolute;width:62px;height:62px;left:50%;top:50%;transform:translate(-50%,-50%);border-radius:50%;background:radial-gradient(circle,#3c494b,#182224 67%);border:2px solid #536062;display:grid;place-items:center;color:#c5d0bf;font:20px Georgia,serif}.wheel-label{position:absolute;top:4px;color:#85918d;font:7px 'DM Mono',monospace;letter-spacing:1px}.pedal-row{position:absolute;right:calc(50% - 340px);bottom:9%;display:flex;gap:14px;align-items:flex-end}.pedal{width:39px;height:64px;background:repeating-linear-gradient(0deg,#475253 0px,#475253 3px,#222c2e 4px,#222c2e 7px);transform:perspective(60px) rotateX(10deg);border:3px solid #0b1112;border-radius:4px;box-shadow:0 4px 8px #0b1112;position:relative}.pedal span{position:absolute;inset:0;background:rgba(214,238,135,0);transition:.1s}.pedal small{position:absolute;bottom:-17px;left:50%;transform:translateX(-50%);font:6px 'DM Mono',monospace;color:#98a49e;white-space:nowrap}.ignition{position:absolute;right:calc(50% - 265px);top:31%;display:flex;gap:5px;align-items:center;color:#909b95;font:7px 'DM Mono',monospace}.key-icon{font-size:15px;color:#c3d38e}.controls{position:absolute;z-index:5;left:50%;bottom:17px;transform:translateX(-50%);width:min(780px,90vw);display:flex;align-items:flex-end;justify-content:center;gap:12px}.steer-controls{display:flex;gap:6px;margin-right:auto}.control-btn{height:62px;width:54px;border:1px solid rgba(255,255,255,.32);background:rgba(13,23,23,.64);backdrop-filter:blur(10px);border-radius:4px;font:30px Manrope,sans-serif;color:var(--cream);line-height:1}.control-btn small{display:block;font:7px 'DM Mono',monospace;letter-spacing:1px;color:#b9c3b9}.gear-controls{display:flex;align-items:center;gap:7px;border:1px solid rgba(255,255,255,.25);background:rgba(13,23,23,.7);padding:6px;border-radius:4px;height:62px}.gear-controls>span{display:flex;flex-direction:column;align-items:center;min-width:28px}.gear-controls small{font:7px 'DM Mono',monospace;color:#9ba69e;letter-spacing:1px}.gear-controls b{font:15px 'DM Mono',monospace;color:var(--lime)}.shift-btn{width:30px;height:46px;background:#273331;border:1px solid #45524a;border-radius:2px;font:22px Manrope;color:var(--lime)}.pedal-btn{height:70px;min-width:91px;position:relative;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;border:1px solid rgba(255,255,255,.22);background:rgba(14,24,24,.74);backdrop-filter:blur(9px);border-radius:4px;overflow:hidden;transition:transform .08s,border .15s}.pedal-btn:active,.pedal-btn.active{transform:translateY(2px);border-color:var(--lime)}.pedal-btn b{font-size:8px;letter-spacing:.7px}.pedal-btn small{font:6px 'DM Mono',monospace;color:#9ba59d;letter-spacing:.5px}.pedal-icon{font-size:14px;color:#c8d78e}.gas-btn{border-color:rgba(214,238,135,.45);background:rgba(37,49,33,.8);min-width:112px}.gas-btn .pedal-icon{color:var(--lime)}.button-meter{position:absolute;bottom:0;left:0;right:0;height:3px;background:rgba(255,255,255,.12)}.button-meter i{display:block;width:0;height:100%;background:var(--lime);transition:width .05s}.brake-btn .button-meter i{background:var(--orange)}.handbrake-btn{height:62px;width:62px;display:flex;flex-direction:column;gap:4px;align-items:center;justify-content:center;background:rgba(14,24,24,.7);border:1px solid rgba(255,255,255,.23);border-radius:4px}.handbrake-btn span{font-size:19px;color:#c2ccbe}.handbrake-btn small{font:6px 'DM Mono',monospace;color:#9ba69e}.handbrake-btn.active{border-color:var(--orange);background:rgba(76,38,26,.7)}.engine-fab{position:absolute;z-index:4;left:4.2%;bottom:6%;display:flex;gap:11px;align-items:center;text-align:left;background:rgba(17,27,26,.75);border:1px solid rgba(214,238,135,.48);padding:11px 17px;border-radius:3px;backdrop-filter:blur(8px)}.power-icon{font-size:20px;color:var(--lime)}.engine-fab b,.engine-fab small{display:block}.engine-fab b{font:9px 'DM Mono',monospace;letter-spacing:1.2px}.engine-fab small{font:7px 'DM Mono',monospace;color:#aab5aa;margin-top:3px}.engine-fab.running .power-icon{color:var(--orange)}.mobile-hint{display:none}
/* screens */
.modal-screen{position:absolute;z-index:10;inset:0;display:flex;align-items:center;justify-content:center;background:rgba(10,18,18,.36);backdrop-filter:blur(5px);animation:fadein .3s ease}.hidden{display:none!important}.welcome-card{width:min(440px,calc(100vw - 36px));padding:36px 40px 30px;background:#f0ede3;color:#172321;box-shadow:0 25px 90px rgba(0,0,0,.4);position:relative}.welcome-card:after{content:"";position:absolute;inset:9px;border:1px solid rgba(23,35,33,.12);pointer-events:none}.welcome-top{display:flex;justify-content:space-between;align-items:center;margin-bottom:31px}.brand-mark.large{border-color:#617168;color:#293d36;width:42px;height:42px;font-size:27px}.welcome-tag{font:8px 'DM Mono',monospace;letter-spacing:1.2px;color:#6d7a70}.welcome-card .eyebrow{color:#65774c;margin:0;font-size:9px}.welcome-card h2{font-size:50px;line-height:.98;letter-spacing:-2.8px;margin:14px 0 13px;font-weight:600}.welcome-card h2 em{font-family:Georgia,serif;font-weight:400;color:#73874c}.welcome-copy{font-size:12px;line-height:1.75;color:#65716a;max-width:310px;margin:0 0 22px}.lesson-preview{display:flex;align-items:center;gap:12px;border-top:1px solid #d6d9cd;border-bottom:1px solid #d6d9cd;padding:13px 0;margin-bottom:19px}.preview-icon{font:12px 'DM Mono',monospace;color:#78894c;border:1px solid #aeb99b;border-radius:50%;width:30px;height:30px;display:grid;place-items:center}.lesson-preview span:nth-child(2){flex:1}.lesson-preview b,.lesson-preview small{display:block}.lesson-preview b{font:9px 'DM Mono',monospace;letter-spacing:.8px}.lesson-preview small{font:7px 'DM Mono',monospace;color:#839087;letter-spacing:.4px;margin-top:4px}.preview-time{font:8px 'DM Mono',monospace;color:#839087}.primary-btn{position:relative;z-index:1;width:100%;height:49px;display:flex;align-items:center;justify-content:space-between;padding:0 17px;background:#233b32;color:#f5f2e9;font:9px 'DM Mono',monospace;letter-spacing:1.3px}.primary-btn span{font-size:16px;color:var(--lime)}.primary-btn:hover{background:#355143}.input-note{text-align:center;margin-top:14px;color:#9ba49a;font:7px 'DM Mono',monospace;letter-spacing:.55px}.input-note i{font-style:normal;color:#a0aa7a;margin:0 5px}.compact{width:min(390px,calc(100vw - 36px));padding-top:45px}.compact .eyebrow{margin-bottom:13px}.compact h2{font-size:46px}.compact .primary-btn{margin-top:21px}.text-btn{position:relative;z-index:1;display:block;margin:14px auto 0;color:#7a877d;background:transparent;font:8px 'DM Mono',monospace;letter-spacing:1px}.finish-medal{width:43px;height:43px;display:grid;place-items:center;background:#e1e9ce;color:#667a44;border-radius:50%;font-size:22px;margin-bottom:20px}.result-stats{display:flex;justify-content:space-between;border-top:1px solid #d4d8cb;border-bottom:1px solid #d4d8cb;padding:13px 4px}.result-stats span{display:flex;flex-direction:column;gap:5px}.result-stats b{font:15px 'DM Mono',monospace;color:#273d32}.result-stats small{font:7px 'DM Mono',monospace;color:#8b968b;letter-spacing:1px}@keyframes fadein{from{opacity:0}to{opacity:1}}
@media(max-width:800px){.topbar{height:65px;padding:14px 18px}.lesson-pill{gap:7px;padding:9px 10px;font-size:8px}.brand{font-size:12px}.brand-mark{width:32px;height:32px}.mission-card{left:5%;top:17%;width:255px}.mission-card h1{font-size:39px}.mission-card p{font-size:11px;max-width:240px}.mission-progress{margin:15px 0 11px}.route-badge{right:4%;top:43%;transform:scale(.88);transform-origin:right center}.speed-card{top:12%;right:4%;width:91px;height:91px}.speed-value span{font-size:33px}.gear-card{right:calc(4% + 98px);top:14%}.status-pills{right:4%;top:calc(12% + 99px)}.cockpit{height:34%;min-height:220px;clip-path:polygon(0 22%,18% 8%,36% 0,64% 0,82% 8%,100% 22%,100% 100%,0 100%)}.cluster{top:10%;transform:translateX(-50%) scale(.82)}.pedal-row{right:calc(50% - 264px);bottom:9%;transform:scale(.85)}.ignition{right:calc(50% - 217px);top:30%}.controls{width:94vw;bottom:12px;gap:7px}.steer-controls{gap:5px}.control-btn{width:42px;height:55px}.gear-controls{height:55px;padding:4px;gap:4px}.shift-btn{width:26px;height:43px}.pedal-btn{height:62px;min-width:69px}.pedal-btn b{font-size:7px}.pedal-btn small{font-size:5px}.gas-btn{min-width:83px}.handbrake-btn{height:55px;width:48px}.engine-fab{bottom:calc(34% + 11px);left:5%;padding:8px 11px}.engine-fab b{font-size:8px}.engine-fab small{font-size:6px}.steering-wrap{bottom:-52px;transform:translateX(-50%) scale(.78);transform-origin:top center}}
@media(max-width:560px){.game-shell{min-height:560px}.topbar{padding:10px 12px}.brand{gap:7px;letter-spacing:1px}.brand small{font-size:7px}.lesson-pill{font-size:7px;gap:6px;padding:8px}.lesson-pill i{height:8px}.top-actions{gap:5px}.icon-btn{width:32px;height:32px}.mission-card{top:13%;left:6%;width:198px}.mission-card .eyebrow{font-size:8px}.mission-card h1{font-size:34px;letter-spacing:-1.6px;margin:12px 0 8px}.mission-card p{font-size:10px;line-height:1.55;max-width:192px}.mission-progress{margin:11px 0 8px;gap:8px}.progress-track{width:95px}.mission-progress,.tip-row{font-size:8px}.tip-icon{font-size:13px}.tip-row b{font-size:8px}.speed-card{top:11%;right:4%;width:72px;height:72px}.speed-value span{font-size:28px}.speed-value small{font-size:7px}.speed-bottom{font-size:6px}.gear-card{top:12%;right:calc(4% + 74px);width:51px}.gear-card strong{font-size:24px}.gear-card small,.gear-card span{font-size:6px}.status-pills{top:calc(11% + 78px);right:3%;gap:4px}.status-pill{padding:5px 6px;font-size:6px}.route-badge{top:39%;right:3%;padding:8px 10px;transform:scale(.76)}.cockpit{height:31%;min-height:212px;clip-path:polygon(0 19%,20% 6%,37% 0,63% 0,80% 6%,100% 19%,100% 100%,0 100%)}.cluster{top:7%;transform:translateX(-50%) scale(.67)}.steering-wrap{transform:translateX(-50%) scale(.62);bottom:-67px}.pedal-row{right:calc(50% - 204px);bottom:8%;transform:scale(.66);transform-origin:right bottom}.ignition{right:calc(50% - 164px);top:25%;font-size:6px}.controls{width:100%;padding:0 8px;bottom:8px;gap:5px}.steer-controls{gap:3px}.control-btn{height:49px;width:35px;font-size:25px}.control-btn small{font-size:5px}.gear-controls{height:49px;gap:3px;padding:3px}.gear-controls>span{min-width:19px}.gear-controls small{font-size:5px}.gear-controls b{font-size:12px}.shift-btn{width:22px;height:39px;font-size:18px}.pedal-btn{height:55px;min-width:57px}.pedal-btn b{font-size:6px;letter-spacing:0}.pedal-btn small{font-size:4px;letter-spacing:0}.gas-btn{min-width:67px}.pedal-icon{font-size:12px}.handbrake-btn{height:49px;width:37px;gap:1px}.handbrake-btn span{font-size:15px}.handbrake-btn small{font-size:4px}.engine-fab{bottom:calc(31% + 10px);padding:7px 9px;gap:7px}.power-icon{font-size:15px}.engine-fab b{font-size:7px}.engine-fab small{font-size:5px}.mobile-hint{display:block;position:absolute;z-index:5;bottom:calc(31% + 8px);right:6%;font:7px 'DM Mono',monospace;color:rgba(255,255,255,.8);text-shadow:0 1px 3px #000}.mobile-hint span{color:var(--lime);font-size:12px}.welcome-card{padding:29px 27px 25px}.welcome-card h2{font-size:43px}.welcome-top{margin-bottom:24px}.welcome-copy{font-size:11px}.welcome-tag{font-size:7px}.warning-toast{top:29%;font-size:9px;white-space:nowrap}}
@media(max-height:650px) and (min-width:561px){.mission-card{top:14%}.cockpit{height:33%}.controls{bottom:7px}.engine-fab{bottom:calc(33% + 8px)}.speed-card{top:11%;width:95px;height:95px}.status-pills{top:calc(11% + 104px)}}

(() => {
  'use strict';
  const $ = (id) => document.getElementById(id);
  const canvas = $('scene'), ctx = canvas.getContext('2d');
  const state = {
    started:false, paused:false, complete:false, engine:false, gear:0, speed:0, rpm:0, distance:0,
    steering:0, roadOffset:0, gas:0, brake:0, clutch:0, handbrake:true, stage:0, elapsed:0,
    maxSpeed:0, penalty:0, toastTimer:0, sound:true, keys:{}, pointer:{}, lastTime:0, lane:0,
    audio:null, oscillator:null, gain:null
  };
  const gearNames = ['R','N','1','2','3','4','5'];
  const stageData = [
    ['YOUR FIRST DRIVE','Ready when\nyou are.','Get familiar with the controls. Start the engine, then ease away from the line.','Press ENGINE to wake the car.'],
    ['SET UP TO MOVE','Find first gear.','Hold the clutch in, shift into first, then release the parking brake.','CLUTCH in · SHIFT + · HANDBRAKE off'],
    ['FEEL THE BITE','Easy does it.','Feed in a little throttle. Let the clutch out smoothly and build to 25 km/h.','Aim for the bite point · ease onto GAS'],
    ['BRING IT HOME','Smooth and steady.','Brake gently before the marker and come to a complete stop in the training bay.','BRAKE to stop · keep the steering straight']
  ];
